      "most_likely_effort": 8
    },
    {
      "activity_id": "A1.4",
      "activity_name": "Implement V1_1 capability definitions",
      "activity_description": "Create the concrete implementations under common/capabilities/{channel,application,orderer}.go for the V1_1 capability, mapping each method on the interface to the appropriate value based on the capability string being set.",
      "most_likely_effort": 16
