      "most_likely_effort": 12
    },
    {
      "activity_id": "A3.3",
      "activity_name": "Publish video and embed in docs",
      "activity_description": "Upload the produced video and add a documentation page that links it alongside a short textual walkthrough of the same procedure.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A4.1",
      "activity_name": "Design CouchDB performance benchmark suite",
      "activity_description": "Define a representative set of query workloads (rich queries with selector, range queries on indexed fields, paginated queries) and the metrics to capture (latency p50/p95/p99, throughput).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4.2",
      "activity_name": "Implement benchmark code and orchestration",
      "activity_description": "Implement Go benchmarks driving the peer with CouchDB as state DB, including a small CLI/script that seeds data, warms the DB, and runs each query workload in a controlled loop.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4.3",
      "activity_name": "Run benchmarks and produce results document",
