      "most_likely_effort": 12
    },
    {
      "activity_id": "A5.1",
      "activity_name": "Design MSPConfig interface and migration plan",
      "activity_description": "Define the MSPConfig interface with the methods needed by configtxgen and the config bundle, and plan how to keep the existing concrete struct as a backward-compatible reference implementation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5.2",
      "activity_name": "Refactor configtxgen to consume MSPConfig interface",
      "activity_description": "Update configtxgen to depend on MSPConfig interface rather than the concrete struct, allowing alternative implementations to be plugged in by callers or other tools.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5.3",
      "activity_name": "Add programmatic channel config block construction",
      "activity_description": "Provide a public Go API that allows assembling a channel config block without YAML, using builders for organizations, orderers, application groups, policies, and capabilities, and serializing through the existing configtx factory.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5.4",
      "activity_name": "MSPConfig interface tests and documentation",
